inside(p,ring){let yes=false;for(let i=0,j=ring.length-1;i<ring.length;j=i++){const a=ring[i],b=ring[j];if((a[1]>p[1])!==(b[1]>p[1])&&p[0]<(b[0]-a[0])*(p[1]-a[1])/(b[1]-a[1])+a[0])yes=!yes}return yes}
cross(a,b,c,d){const orient=(p,q,r)=>(q[0]-p[0])*(r[1]-p[1])-(q[1]-p[1])*(r[0]-p[0]),on=(p,q,r)=>r[0]>=Math.min(p[0],q[0])-1e-10&&r[0]<=Math.max(p[0],q[0])+1e-10&&r[1]>=Math.min(p[1],q[1])-1e-10&&r[1]<=Math.max(p[1],q[1])+1e-10,A=orient(a,b,c),B=orient(a,b,d),C=orient(c,d,a),D=orient(c,d,b);return A*B<0&&C*D<0||Math.abs(A)<1e-10&&on(a,b,c)||Math.abs(B)<1e-10&&on(a,b,d)||Math.abs(C)<1e-10&&on(c,d,a)||Math.abs(D)<1e-10&&on(c,d,b)}
