geom(g){if(!g)return"";const cc=x=>x.map(p=>this.coord(p)).join(" "),pt=x=>"<Point><coordinates>"+this.coord(x)+"</coordinates></Point>",ln=x=>"<LineString><tessellate>1</tessellate><coordinates>"+cc(x)+"</coordinates></LineString>",pg=x=>"<Polygon><outerBoundaryIs><LinearRing><coordinates>"+cc(x[0]||[])+"</coordinates></LinearRing></outerBoundaryIs>"+x.slice(1).map(r=>"<innerBoundaryIs><LinearRing><coordinates>"+cc(r)+"</coordinates></LinearRing></innerBoundaryIs>").join("")+"</Polygon>";switch(g.type){case"Point":return pt(g.coordinates);case"MultiPoint":return"<MultiGeometry>"+g.coordinates.map(pt).join("")+"</MultiGeometry>";case"LineString":return ln(g.coordinates);case"MultiLineString":return"<MultiGeometry>"+g.coordinates.map(ln).join("")+"</MultiGeometry>";case"Polygon":return pg(g.coordinates);case"MultiPolygon":return"<MultiGeometry>"+g.coordinates.map(pg).join("")+"</MultiGeometry>";case"GeometryCollection":return"<MultiGeometry>"+(g.geometries||[]).map(x=>this.geom(x)).join("")+"</MultiGeometry>";default:return""}}
kml(items){const folders=new Map();for(const x of items){const id=x.d.id.replace(/[^a-z0-9_-]/gi,"_");if(!folders.has(id))folders.set(id,{name:x.d.name,color:this.color(this.getColor(x.f,x.d)),items:[]});folders.get(id).items.push(x)}let s='<?xml version="1.0" encoding="UTF-8"?><kml xmlns="http://www.opengis.net/kml/2.2"><Document><name>Selecție rețea ORO</name>';for(const[id,folder]of folders){s+='<Style id="s_'+id+'"><LineStyle><color>'+folder.color+'</color><width>2.5</width></LineStyle><PolyStyle><color>'+folder.color+'</color><fill>0</fill></PolyStyle><IconStyle><color>'+folder.color+'</color><scale>1.1</scale><Icon><href>http://maps.google.com/mapfiles/kml/shapes/placemark_circle.png</href></Icon></IconStyle></Style><Folder><name>'+this.xml(folder.name)+'</name>';for(const{f}of folder.items){const p=f.properties||{},name=p.n||p.Cod||p.name||f.id||"Element rețea",desc=Object.entries(p).filter(([k,v])=>!k.startsWith("_")&&v!==null&&v!=="").map(([k,v])=>k+": "+v).join("\n");s+='<Placemark><name>'+this.xml(name)+'</name><styleUrl>#s_'+id+'</styleUrl>'+(desc?'<description>'+this.xml(desc)+'</description>':"")+this.geom(f.geometry)+'</Placemark>'}s+="</Folder>"}return s+"</Document></kml>"}
